// ReplyToMessageMalformedSource is the manifest mock malformedSource: Gmail returned a source message that cannot be decoded, so no reply is sent.
func ReplyToMessageMalformedSource() connectormock.Case[gmail.SendMessageOutput] {
	var value gmail.SendMessageOutput
	return connectormock.Branch(gmail.ReplyToMessageBranchInvalidResponse, value, &sdkgo.Failure{Kind: sdkgo.FailureProtocol, Message: "Gmail returned an invalid source message."})
}

// ReplyToMessageConnectionLost is the manifest mock connectionLost: The connection closed after dispatch and Sent Mail found nothing; the next attempt searches again and resends the reply with the same Message-ID while below the send cap.
func ReplyToMessageConnectionLost() connectormock.Case[gmail.SendMessageOutput] {
	return connectormock.Retry[gmail.SendMessageOutput](sdkgo.Failure{Kind: sdkgo.FailureTransport, Message: "The connection closed before Gmail answered."}, time.Duration(0))
}

// ReplyToMessageEmptyBody is the manifest mock emptyBody: The reply has no body, so no request is sent.
func ReplyToMessageEmptyBody() connectormock.Case[gmail.SendMessageOutput] {
	var value gmail.SendMessageOutput
	return connectormock.Branch(gmail.ReplyToMessageBranchDefect, value, &sdkgo.Failure{Kind: sdkgo.FailureValidation, Message: "The reply body is required."})
}

// ReplyToMessageDefault is the manifest default, repliedInThread, which New installs.
func ReplyToMessageDefault() connectormock.Case[gmail.SendMessageOutput] {
	return ReplyToMessageRepliedInThread()
}
